export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayInput = signal('');
  protected readonly asOfInput = signal('');
  protected readonly asOfError = signal<string | null>(null);
  protected readonly cloneInput = signal('');
  /** The id of the last clone made of the sheet from this screen; blank for none. */
  protected readonly clonedTo = signal('');

  protected async signIn(event: Event): Promise<void> {
    event.preventDefault();
    this.signinError.set(null);
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Enter a name to sign in.');
      return;
    }
    try {
      await this.session.signIn(name);
    } catch {
      this.signinError.set('Could not sign in.');
    }
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id to load.');
      return;
    }
    try {
      if (id !== this.session.sheet()) this.clonedTo.set('');
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('Could not load that sheet.');
    }
  }

  protected async saveToday(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.sheetError.set('Enter a date for today.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.sheetError.set('Could not change the sheet\'s today.');
    }
  }

  protected async setAsOf(event: Event): Promise<void> {
    event.preventDefault();
    this.asOfError.set(null);
    const date = this.asOfInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.asOfError.set('Enter a date to show the sheet as of.');
      return;
    }
    try {
      await this.session.setAsOf(date);
    } catch {
      this.asOfError.set('Could not show the sheet as of that date.');
    }
  }

  protected async clearAsOf(): Promise<void> {
    this.asOfError.set(null);
    try {
      await this.session.clearAsOf();
    } catch {
      this.asOfError.set('Could not show the sheet as it is now.');
    }
  }

  protected async cloneSheet(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const to = this.cloneInput().trim();
    if (!to) {
      this.sheetError.set('Enter a sheet id to clone to.');
      return;
    }
    try {
      this.clonedTo.set(await this.session.cloneSheet(to));
    } catch {
      this.sheetError.set('Could not clone the sheet to that id.');
    }
  }

  protected async archive(): Promise<void> {
    this.sheetError.set(null);
    try {
      await this.session.archive();
    } catch {
      this.sheetError.set('Could not archive the sheet.');
    }
  }
}
import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { Component, input } from '@angular/core';
import { StatusSummary } from '../summary/summary';

// The sheet's counters, shown at all times above everything else on it: how many people are on the
// sheet (retired people included), how many claims are in each status (as the summary counts them)
// and the sheet's due- and overdue-totals (as the people list's totals show them). Then the same
// figures consolidated over the sheet and all its descendants (the sheets naming it as parent, and
// theirs): each sheet's as that sheet shows it, added up; a sheet with no children shows its own.
// Last, the signed-in user's own figures: the due- and overdue-totals of the person on the sheet
// with the user's name (by name or alias); blank when there is no such person.
@Component({
  selector: 'app-header',
  template: `
    <header aria-label="Sheet counters">
      <dl>
        <dt>People</dt>
        <dd data-testid="header-people-count">{{ peopleCount() }}</dd>
        @for (s of statuses(); track s.status) {
          <dt>{{ s.status }}</dt>
          <dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count }}</dd>
        }
        <dt>Due</dt>
        <dd data-testid="header-due-total">{{ dueTotal() }}</dd>
        <dt>Overdue</dt>
        <dd data-testid="header-overdue-total">{{ overdueTotal() }}</dd>
      </dl>
      <dl aria-label="Consolidated over the sheet and its descendants">
        <dt>People, with sub-sheets</dt>
        <dd data-testid="consolidated-people-count">{{ consolidatedPeopleCount() }}</dd>
        <dt>Due, with sub-sheets</dt>
        <dd data-testid="consolidated-due-total">{{ consolidatedDueTotal() }}</dd>
        <dt>Overdue, with sub-sheets</dt>
        <dd data-testid="consolidated-overdue-total">{{ consolidatedOverdueTotal() }}</dd>
      </dl>
      <dl aria-label="My figures">
        <dt>My due</dt>
        <dd data-testid="my-due-total">{{ myDueTotal() }}</dd>
        <dt>My overdue</dt>
        <dd data-testid="my-overdue-total">{{ myOverdueTotal() }}</dd>
      </dl>
    </header>
  `,
})
export class Header {
  readonly peopleCount = input.required<number>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();
  readonly consolidatedPeopleCount = input.required<number>();
  readonly consolidatedDueTotal = input.required<string>();
  readonly consolidatedOverdueTotal = input.required<string>();
  readonly myDueTotal = input.required<string>();
  readonly myOverdueTotal = input.required<string>();
}

